BEGIN;
CREATE TABLE enterprise_workflow.publications(enterprise_id uuid NOT NULL,id uuid NOT NULL,team_id uuid NOT NULL,order_id uuid NOT NULL,task_id uuid NOT NULL,shop_id uuid NOT NULL,target_key text NOT NULL,version integer NOT NULL CHECK(version>0),status text NOT NULL,document jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(enterprise_id,id),FOREIGN KEY(enterprise_id,team_id) REFERENCES enterprise_workflow.teams(enterprise_id,team_id),FOREIGN KEY(enterprise_id,order_id) REFERENCES enterprise_workflow.orders(enterprise_id,id),FOREIGN KEY(enterprise_id,shop_id) REFERENCES enterprise_workflow.catalog_entities(enterprise_id,id),CHECK((document->>'version')::integer=version),CHECK(document->>'status'=status));
CREATE UNIQUE INDEX publication_active_target ON enterprise_workflow.publications(enterprise_id,target_key) WHERE status IN ('draft','approved','executing','unknown','manual_published','recall_requested','recall_unknown');
CREATE INDEX publication_team ON enterprise_workflow.publications(enterprise_id,team_id,updated_at DESC,id);
CREATE TABLE enterprise_workflow.publication_commands(enterprise_id uuid NOT NULL,id uuid NOT NULL,publication_id uuid NOT NULL,subject text NOT NULL,fingerprint text NOT NULL,applied_version integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(enterprise_id,id));
CREATE TABLE enterprise_workflow.publication_revisions(enterprise_id uuid NOT NULL,publication_id uuid NOT NULL,revision integer NOT NULL,command_id uuid NOT NULL,actor text NOT NULL,reason text NOT NULL,action text NOT NULL,document jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(enterprise_id,publication_id,revision),FOREIGN KEY(enterprise_id,publication_id) REFERENCES enterprise_workflow.publications(enterprise_id,id),FOREIGN KEY(enterprise_id,command_id) REFERENCES enterprise_workflow.publication_commands(enterprise_id,id));
INSERT INTO enterprise_workflow.schema_version VALUES(30);
COMMIT;
